-- Migration 013 companion: canonical service page content
-- Generated from lib/ServiceDefaults.php — do not edit by hand.
-- Safe to import more than once: services are upserted by slug and
-- sections/items are only created when the service has none yet.

SET NAMES utf8mb4;

-- ========================================================================
-- Service: Web Development (web-development)
-- ========================================================================
UPDATE services SET slug = 'web-development' WHERE (slug IS NULL OR slug = '') AND title = 'Web Development' LIMIT 1;
    ON DUPLICATE KEY UPDATE title = VALUES(title), card_title = VALUES(card_title), description = VALUES(description), short_description = VALUES(short_description), full_description = VALUES(full_description), image = VALUES(image), image_alt = VALUES(image_alt), hero_image = VALUES(hero_image), hero_subtitle = VALUES(hero_subtitle), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), seo_keywords = VALUES(seo_keywords), service_category = VALUES(service_category), card_link = VALUES(card_link), icon = VALUES(icon), list_items = VALUES(list_items), sort_order = VALUES(sort_order), is_active = VALUES(is_active), show_homepage = VALUES(show_homepage), show_listing = VALUES(show_listing);
SET @sid := (SELECT id FROM services WHERE slug = 'web-development');
SET @seed := (SELECT COUNT(*) = 0 FROM service_sections WHERE service_id = @sid);










