INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'What is included in a tourism website?', 'A tourism website typically includes a homepage, tour and package pages, destination and attraction pages, photo galleries, itinerary layouts, an enquiry form, and contact details. Additional modules such as booking systems or management dashboards are available as custom development.', NULL, NULL, 0, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can you build safari and tour booking systems?', 'Yes. We build enquiry and booking systems for safaris and tours. The exact workflow, whether enquiry-only, request-to-book, or full online booking, is defined with you during planning and delivered as custom development.', NULL, NULL, 1, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can visitors book tours directly through our website?', 'Yes, where the agreed project scope includes an online booking workflow. Many operators start with an enquiry system and add direct booking and online payments as a later phase.', NULL, NULL, 2, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can you integrate mobile money and online payments?', 'Payment integration is available as a custom feature and depends on your chosen provider and account approvals. We integrate suitable gateways, such as mobile money and card processors, once your merchant accounts are ready.', NULL, NULL, 3, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can we manage tours, prices, and bookings through an admin dashboard?', 'Yes. A tour management dashboard is available as custom development, allowing your team to manage tours, packages, prices, enquiries, and bookings. The exact features are agreed before development begins.', NULL, NULL, 4, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can the website display itineraries, destinations, galleries, and tour packages?', 'Yes. We design destination and attraction pages, day-by-day itineraries, tour package listings, and responsive photo galleries as part of the standard tourism website.', NULL, NULL, 5, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can you build a multilingual tourism website?', 'Yes. We can build multilingual tourism websites so you can serve visitors in different languages, such as English and Kiswahili, with a language switcher.', NULL, NULL, 6, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Do you provide hosting, domain setup, and maintenance?', 'Yes. We assist with domain registration, hosting setup, security configuration, and ongoing maintenance and support as part of our service.', NULL, NULL, 7, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'Can the website be optimized for search engines?', 'Yes. We follow SEO best practices when building your website, and can provide ongoing SEO and digital marketing services to help travellers find your business online.', NULL, NULL, 8, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
INSERT INTO service_section_items (section_id, item_title, item_text, item_icon, item_link, sort_order, is_active) SELECT id, 'How do we get started?', 'Simply contact us with your requirements. We will discuss your goals, recommend the right scope, and provide a quotation and timeline for your tourism website project.', NULL, NULL, 9, 1 FROM service_sections WHERE service_id = @sid AND sort_order = 1 AND @seed;
